INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template) VALUES
  (45, 1, '명령, 옵션, 인자 구분해서 읽기', '`tar -czvf backup.tgz /etc` 를 처음 봤습니다. 이 한 줄을 **명령 / 옵션 / 인자**로 나눠 읽으면 어떻게 될까요?', '맨 앞이 실행할 프로그램(명령), `-` 로 시작하는 것이 동작을 바꾸는 옵션, 나머지는 명령이 다룰 대상(인자)입니다.', NULL, NULL, '[]', 'choice', '["명령 `tar`, 옵션 `-czvf`, 인자 `backup.tgz` 와 `/etc`", "명령 `tar -czvf`, 옵션 `backup.tgz`, 인자 `/etc`", "명령 `-czvf`, 옵션 `tar`, 인자 `backup.tgz /etc`", "전부 명령이다"]', 0, '명령(프로그램)은 맨 앞의 `tar`, `-` 로 시작하는 `-czvf` 는 옵션(동작을 바꾸는 스위치), 나머지 `backup.tgz`(만들 파일)와 `/etc`(묶을 대상)는 인자입니다. 모르는 명령은 **이렇게 세 조각으로 나눠 놓고 한 조각씩** 의미를 찾으면 읽을 수 있습니다.', NULL, NULL),
  (45, 2, 'tar 옵션 뜻을 읽고 빈칸 채우기', '`/etc` 를 **묶고(create) gzip 으로 압축해서** `backup.tgz` 파일로 만들려고 합니다. 옵션의 뜻은 `c` 묶기(create), `z` gzip 압축, `f` 파일 이름 지정입니다. 빈칸을 채우세요.', '묶으려면 `c`, 압축하려면 `z`, 만들 파일 이름을 바로 뒤에 쓰려면 `f` 가 필요합니다. 풀기(`x`)나 목록 보기(`t`)와 헷갈리지 마세요.', NULL, NULL, '[]', 'fill', '["-czf", "-xzf", "-tzf", "-cf"]', NULL, '`-czf` = create(묶기) + gzip 압축 + file(파일 이름 지정)입니다. `-xzf` 는 압축을 **풀 때**(extract), `-tzf` 는 안에 무엇이 있는지 **목록만 볼 때**(list), `-cf` 는 묶기만 하고 압축은 하지 않습니다. 옵션은 한 글자씩 뜻이 있으니 하나씩 풀어 읽으면 됩니다.', '[0]', 'tar {0} backup.tgz /etc'),
  (45, 3, '낯선 명령을 쓰기 전의 안전한 순서대로 놓기', '인터넷에서 본 `rm /tmp/old*` 라는 명령을 써 보려고 합니다. 그냥 붙여 넣지 않고 **안전한 순서**로 해 보려면 어떻게 해야 할까요? 순서대로 놓으세요.', '뜻을 먼저 알아보고, 지울 대상이 맞는지 눈으로 확인한 뒤, 실행하고, 결과를 확인합니다. 삭제는 되돌릴 수 없습니다.', NULL, NULL, '[]', 'order', '["`rm /tmp/old*` 로 실제 지우기", "`ls /tmp/old*` 로 지울 대상이 맞는지 먼저 보기", "`rm --help` 로 명령과 옵션의 뜻 읽기", "`ls /tmp` 로 결과 확인하기"]', NULL, '**뜻 읽기(`--help`/`man`) → 대상 미리 보기(같은 패턴을 `ls` 로) → 실행 → 결과 확인** 순서입니다. 특히 `*` 같은 패턴은 생각보다 많이 잡힐 수 있어서, 지우기 전에 `ls` 로 같은 패턴을 먼저 보는 습관이 사고를 막아 줍니다.', '[2, 1, 0, 3]', NULL),
  (45, 4, '복사해서 붙이기 전에 가장 조심해야 할 명령 고르기', '인터넷에서 찾은 명령 네 개 중 **붙여 넣기 전에 가장 조심해서 읽어야 하는** 것은 무엇일까요?', '되돌릴 수 없고 범위가 넓은 명령이 위험합니다. `~` 는 홈 디렉터리, `*` 는 전부를 뜻합니다.', NULL, NULL, '[]', 'choice', '["`ls -l /etc`", "`cat /etc/hosts`", "`rm -rf ~/*`", "`pwd`"]', 2, '`rm -rf ~/*` 는 홈 디렉터리 안의 **모든 것을 확인 없이 지웁니다.** (`-r` 하위 폴더까지, `-f` 묻지 않고) `ls`, `cat`, `pwd` 는 읽기만 하는 명령이라 위험하지 않습니다. 지우는(`rm`), 덮어쓰는(`>`), 권한을 바꾸는(`chmod -R`) 명령은 특히 의미를 확인하고 실행하세요.', NULL, NULL),
  (45, 5, '> 로 덮어쓰기가 위험한 이유 알기', '`/etc/hosts` 에 줄 하나를 추가하려고 `echo "10.0.0.5 web" > /etc/hosts` 를 실행했습니다. 무슨 일이 생길까요?', '`>` 는 파일을 새로 만들며 **기존 내용을 지웁니다.** 기존 내용 뒤에 붙이는 기호는 따로 있습니다.', NULL, NULL, '[]', 'choice', '["기존 내용 뒤에 한 줄이 추가된다", "기존 내용이 모두 지워지고 그 한 줄만 남는다", "아무 일도 일어나지 않는다", "파일이 읽기 전용으로 바뀐다"]', 1, '`>` 는 파일을 **덮어씁니다.** 이 명령은 `/etc/hosts` 의 기존 내용을 모두 지우고 한 줄만 남깁니다. 줄을 **추가**하려면 `>>` 를 씁니다. 중요한 설정 파일에 쓰기 전에는 `cp` 로 백업해 두는 습관이 좋습니다.', NULL, NULL),
  (45, 6, 'curl 결과를 바로 sh 에 넘기는 명령의 위험 알기', '설치 안내에 `curl -s https://example.com/install.sh | sh` 라고 적혀 있습니다. 이 한 줄의 위험은 무엇일까요?', '`|` 는 앞 명령의 출력을 뒤 명령에 넘깁니다. 내려받은 글이 그대로 쉘의 입력이 되면 어떻게 될까요?', NULL, NULL, '[]', 'choice', '["위험이 없다", "내려받은 스크립트의 내용을 보지 않고 바로 실행하게 된다 (내용이 바뀌거나 악의가 있어도 알 수 없다)", "속도가 너무 느려진다", "파일이 두 번 저장된다"]', 1, '`curl ... | sh` 는 내려받은 글(스크립트)을 **읽어 보지도 않고 곧바로 실행**합니다. 더 안전한 방법은 먼저 파일로 받고(`curl -o install.sh ...`), 내용을 읽어 본 뒤(`less`/`cat`) 실행하는 것입니다. 믿을 수 있는 출처인지도 확인하세요.', NULL, NULL),
  (45, 7, '명령 앞 sudo 의 뜻 알기', '복사한 명령 앞에 `sudo` 가 붙어 있습니다. 이것은 무슨 뜻이고, 왜 더 조심해야 할까요?', '`sudo` 는 다른 사용자(보통 관리자 root)의 권한으로 실행하라는 뜻입니다.', NULL, NULL, '[]', 'choice', '["명령을 천천히 실행한다", "관리자(root) 권한으로 실행한다. 시스템 전체에 영향을 줄 수 있어 더 신중히 읽어야 한다", "명령을 취소한다", "명령 결과를 저장한다"]', 1, '`sudo` 는 관리자 권한으로 명령을 실행합니다. 일반 사용자라면 막힐 일(시스템 파일 수정, 서비스 중지, 삭제)도 되어 버리므로, `sudo` 가 붙은 명령은 **무엇을 어디에 하는지** 더 꼼꼼히 확인하고 붙여 넣어야 합니다.', NULL, NULL),
  (45, 8, 'ls 옵션 -lh 읽기', '`ls -lh /var/log` 에서 `-l` 과 `-h` 는 각각 무슨 뜻일까요?', '`-l` 은 길게(long) 자세히, `-h` 는 사람이 읽기 쉽게(human-readable) 입니다. 크기가 어떻게 표시될까요?', NULL, NULL, '[]', 'choice', '["`-l` 숨김 파일까지, `-h` 도움말", "`-l` 자세히(권한·크기·날짜), `-h` 크기를 K·M 같은 읽기 쉬운 단위로", "`-l` 이름 순서, `-h` 최근 것 먼저", "`-l` 한 줄로, `-h` 숨기기"]', 1, '`-l` 은 권한·소유자·크기·날짜를 한 줄씩 **자세히** 보여 주고, `-h`(human-readable)는 크기를 바이트 대신 `4.0K`, `1.2M` 처럼 읽기 쉬운 단위로 바꿉니다. 옵션은 `-lh` 처럼 붙여 쓸 수 있습니다.', NULL, NULL),
  (45, 9, 'df 옵션으로 읽기 쉬운 용량 보기', '디스크 사용량을 보는 `df` 명령의 결과가 바이트 숫자로 길게 나옵니다. **사람이 읽기 쉬운 단위(GB, MB)** 로 보려면 어떤 옵션을 붙여야 할까요? 빈칸을 채우세요.', '앞 문제의 `ls -lh` 의 `h` 와 같은 뜻입니다.', NULL, NULL, '[]', 'fill', '["-h", "-a", "-i", "-T"]', NULL, '`-h`(human-readable)는 `df` 와 `ls`, `du`, `free` 등 여러 명령에서 **읽기 쉬운 단위**를 뜻하는 공통 옵션입니다. `-a` 는 모두, `-i` 는 inode, `-T` 는 파일 시스템 종류를 보여 줍니다. 같은 글자가 명령마다 비슷한 뜻을 가진다는 것을 알아 두면 읽기 쉬워집니다.', '[0]', 'df {0}'),
  (45, 10, '명령을 실행하기 전에 결과 예측하기', '`echo "a b c" | wc -w` 를 실행하면 화면에 무엇이 나올까요? (`wc -w` 는 단어 수를 센다)', '`echo` 가 `a b c` 를 내보내고, `|` 로 `wc -w` 에 넘깁니다. 공백으로 나뉜 덩어리가 단어입니다.', NULL, NULL, '[]', 'choice', '["1", "3", "5", "오류가 난다"]', 1, '`echo "a b c"` 가 `a b c` 를 출력하고 파이프(`|`)로 `wc -w` 가 받아서 공백으로 나뉜 단어 `a`, `b`, `c` 세 개를 셉니다. 실행하기 전에 **결과를 미리 짐작**해 보는 습관은 명령을 이해했는지 확인하는 가장 좋은 방법입니다.', NULL, NULL),
  (45, 11, '연결 기호가 든 명령 한 줄 풀어 읽기', '`cd /tmp && ls | wc -l` 을 풀어서 읽으면 어떻게 될까요?', '`&&` 는 앞이 성공해야 뒤를 실행, `|` 는 앞의 출력을 뒤로 넘깁니다. 왼쪽부터 한 덩어리씩 읽습니다.', NULL, NULL, '[]', 'choice', '["`/tmp` 로 이동하는 데 성공하면, 그곳의 항목 목록을 만들어 개수를 센다", "`/tmp` 와 `ls` 를 동시에 실행한다", "`ls` 의 결과를 `/tmp` 로 이동시킨다", "`/tmp` 가 있든 없든 항상 `wc -l` 만 실행한다"]', 0, '왼쪽부터 읽으면 `cd /tmp` (이동) → 성공하면(`&&`) → `ls`(목록) → 그 출력을 파이프(`|`)로 → `wc -l`(줄 수 세기)입니다. 즉 "/tmp 로 가서 그 안의 항목이 몇 개인지 센다"입니다. 연결 기호를 만나면 거기서 끊어서 한 덩어리씩 읽으세요.', NULL, NULL);
